package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Term     string   `json:"term"`
	Category string   `json:"category"`
	Tags     []string `json:"tags"`
	Limit    int      `json:"limit"`
}

type Product struct {
	ID       int    `json:"id"`
	Name     string `json:"name"`
	Price    float64 `json:"price"`
	Category string `json:"category"`
}

func init() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// buildSearchQuery constructs a dynamic search query based on filters
func buildSearchQuery(req SearchRequest) string {
	base := "SELECT id, name, price, category FROM products WHERE active = true"
	clauses := []string{}

	if req.Term != "" {
		// Full-text search with user-provided term
		clauses = append(clauses, fmt.Sprintf("to_tsvector('english', name || ' ' || description) @@ plainto_tsquery('english', '%s')", req.Term))
	}

	if req.Category != "" {
		clauses = append(clauses, fmt.Sprintf("category = '%s'", req.Category))
	}

	if len(req.Tags) > 0 {
		tagList := strings.Join(req.Tags, "','")
		clauses = append(clauses, fmt.Sprintf("EXISTS (SELECT 1 FROM product_tags pt WHERE pt.product_id = products.id AND pt.tag IN ('%s'))", tagList))
	}

	if len(clauses) > 0 {
		base += " AND " + strings.Join(clauses, " AND ")
	}

	limit := req.Limit
	if limit <= 0 || limit > 100 {
		limit = 20
	}
	base += fmt.Sprintf(" ORDER BY price ASC LIMIT %d", limit)

	return base
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request body", 400)
		return
	}

	// Log the search for analytics
	log.Printf("Search request: term=%q category=%q tags=%v limit=%d from=%s",
		req.Term, req.Category, req.Tags, req.Limit, r.Header.Get("X-Forwarded-For"))

	query := buildSearchQuery(req)
	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Category); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("X-Search-Query-Hash", fmt.Sprintf("%x", len(query)))
	json.NewEncoder(w).Encode(products)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/products/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Printf("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
